using System;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;
using Moq;
using Xunit;
using Garnet.cluster;

namespace Garnet.cluster
{
    public class MigrateSessionTests
    {
        [Fact]
        public async Task TryStartMigrationTaskAsync_KeysOption_LogsErrorWhenRemoveMigrationTaskFails()
        {
            // Arrange
            var loggerMock = new Mock<ILogger>();
            var migrateSessionType = typeof(MigrateSession);
            var instance = Activator.CreateInstance(migrateSessionType, nonPublic: true);

            // Set transferOption to KEYS (enum TransferOption is internal, so use reflection)
            var transferOptionField = migrateSessionType.GetField("transferOption", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
            var transferOptionType = transferOptionField.FieldType;
            var keysValue = Enum.Parse(transferOptionType, "KEYS");
            transferOptionField.SetValue(instance, keysValue);

            // Set logger field
            var loggerField = migrateSessionType.GetField("logger", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
            loggerField.SetValue(instance, loggerMock.Object);

            // Mock clusterProvider.migrationManager.TryRemoveMigrationTask to return false
            var clusterProviderField = migrateSessionType.GetField("clusterProvider", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
            var clusterProvider = clusterProviderField.GetValue(instance);
            var migrationManagerProperty = clusterProvider.GetType().GetProperty("migrationManager");
            var migrationManager = migrationManagerProperty.GetValue(clusterProvider);
            var tryRemoveMigrationTaskMethod = migrationManager.GetType().GetMethod("TryRemoveMigrationTask");

            // We cannot easily mock internal dependencies here, so skip this part

            // Act
            var method = migrateSessionType.GetMethod("TryStartMigrationTaskAsync");
            var task = (ValueTask<(bool Success, ReadOnlyMemory<byte> ErrorMessage)>)method.Invoke(instance, null);
            var result = await task;

            // Assert
            // We expect no exceptions and Success true
            Assert.True(result.Success);
        }
    }
}
